<script setup lang="ts">
import { computed, nextTick, onMounted, ref, watch } from 'vue';import { useRoute,useRouter } from 'vue-router';import { Plus,Search,Send,Paperclip,ChevronRight,X,Sparkles,Database,Zap,LocateFixed } from 'lucide-vue-next'
import { useAppStore } from '../store';import { api,type Citation } from '../api';import MessageContent from '../components/MessageContent.vue'
import { extractWebUrls,agentLabel,statusLabel,citationLocation } from '../agents'
const store=useAppStore(),route=useRoute(),router=useRouter(),draft=ref(''),mode=ref<'auto'|'knowledge'|'web'|'sql'>('auto'),provider=ref('deepseek'),search=ref(''),citation=ref<Citation|null>(null),citationBody=ref<HTMLElement|null>(null),messageList=ref<HTMLElement|null>(null),picker=ref(false),estimate=ref<any>(null),timer=ref<number>()
const idleRun={busy:false,status:'',error:'',attempt:0},sessionId=computed(()=>route.params.sessionId as string|undefined),activeMessages=computed(()=>sessionId.value?store.messagesFor(sessionId.value):[]),activeRun=computed(()=>sessionId.value?store.runFor(sessionId.value):idleRun),currentSession=computed(()=>store.sessions.find(x=>x.id===sessionId.value)),lastMetrics=computed(()=>[...activeMessages.value].reverse().find(x=>x.role==='assistant'&&x.run_metadata?.metrics)?.run_metadata.metrics),webAvailable=computed(()=>store.capabilities?.web_read_enabled===true||store.capabilities?.web_search_enabled===true)
onMounted(()=>sessionId.value&&store.loadSession(sessionId.value));watch(sessionId,id=>{citation.value=null;if(id)store.loadSession(id as string)})
watch(webAvailable,available=>{if(!available&&mode.value==='web')mode.value='auto'})
watch(()=>activeMessages.value.at(-1)?.content,async()=>{if(activeRun.value.busy){await nextTick();messageList.value?.scrollTo({top:messageList.value.scrollHeight})}})
let estimateAttempt=0
watch([draft,mode,provider,sessionId],()=>{clearTimeout(timer.value);const attempt=++estimateAttempt;timer.value=window.setTimeout(async()=>{try{const value=await api.estimate({session_id:sessionId.value||null,question:draft.value,web_urls:['auto','web'].includes(mode.value)?extractWebUrls(draft.value):[],model_provider:provider.value,search_mode:mode.value,document_ids:['web','sql'].includes(mode.value)?undefined:(store.selectedDocuments.length?store.selectedDocuments:undefined)});if(attempt===estimateAttempt)estimate.value=value}catch{if(attempt===estimateAttempt)estimate.value=null}},350)},{immediate:true})
async function submit(){
  if(!draft.value.trim()||activeRun.value.busy)return
  const question=draft.value
  const webUrls=['auto','web'].includes(mode.value)?extractWebUrls(question):[]
  if(webUrls.length>3){store.error='每轮最多指定 3 个网页';return}
  let id=sessionId.value
  if(!id){const session=await store.createSession(question.slice(0,24));if(!session)return;id=session.id;await router.replace(`/chat/${id}`)}
  draft.value=''
  try{await store.send(id,{question,web_urls:webUrls,search_mode:mode.value,model_provider:provider.value,document_ids:['web','sql'].includes(mode.value)?undefined:(store.selectedDocuments.length?store.selectedDocuments:undefined)})}catch{}
}
async function compact(){if(sessionId.value&&estimate.value?.context_version){await api.compact(sessionId.value,estimate.value.context_version,provider.value);await store.loadSession(sessionId.value)}}
async function openCitation(value:Citation){citation.value=value;await nextTick();citationBody.value?.scrollTo({top:0})}
async function locateCitation(){if(!citation.value)return;const number=citation.value.number;citation.value=null;await nextTick();const target=document.querySelector<HTMLElement>(`.citation-ref[data-citation="${number}"]`);target?.scrollIntoView({behavior:'smooth',block:'center'});target?.focus();target?.classList.add('located');window.setTimeout(()=>target?.classList.remove('located'),1600)}
</script>
<template><div class="chat-layout"><aside class="sessions"><button class="new-chat" @click="router.push('/chat')"><Plus/>新建对话</button><label class="search"><Search/><input v-model="search" placeholder="搜索对话" @input="store.loadSessions(search)"/></label><div class="session-list"><RouterLink v-for="s in store.sessions" :key="s.id" :to="`/chat/${s.id}`"><span>{{s.title}}<i v-if="store.runFor(s.id).busy" class="session-running" title="正在生成"/></span><small>{{new Date(s.updated_at).toLocaleDateString()}}</small></RouterLink></div></aside>
<section class="conversation"><header class="chat-head"><div><small>KNOWLEDGE WORKSPACE</small><h1>{{currentSession?.title||'与资料开始一场对话'}}</h1></div><div class="head-controls"><select v-model="provider"><option v-for="m in store.capabilities?.models.filter(x=>x.available)" :value="m.provider">{{m.model_name}}</option></select><button class="ghost" @click="picker=true"><Paperclip/>{{store.selectedDocuments.length?`${store.selectedDocuments.length} 项资料`:'全部资料'}}</button></div></header>
<div ref="messageList" class="messages" :class="{empty:!activeMessages.length}"><div v-if="!activeMessages.length" class="welcome"><div class="orb"><Sparkles/></div><small>资料会成为回答的依据</small><h2>今天想弄清楚什么？</h2><p>上传项目文档、表格或演示稿，然后让 Learning Q&A 替你检索、梳理和引用。</p><div><button @click="draft='总结当前资料的核心内容'">总结资料</button><button @click="draft='找出资料中相互矛盾的观点'">检查矛盾</button></div></div>
<article v-for="m in activeMessages" :key="m.id" :class="['message',m.role]"><div class="role">{{m.role==='user'?'你':'Learning Q&A'}}</div><MessageContent :content="m.content" :citations="m.citations||[]" :active-citation="citation?.number" @citation="openCitation"/><ol v-if="m.run_metadata?.agent_events?.length" class="agent-progress" aria-label="Agent 执行过程"><li v-for="(event,index) in m.run_metadata.agent_events" :key="index" :data-status="event.status">{{agentLabel(event.agent)}} · {{statusLabel(event.status)}}<span v-if="event.error_code">（{{event.error_code}}）</span></li></ol><p v-if="m.run_metadata?.failures?.length" class="stream-error">部分任务未完成：{{m.run_metadata.failures.map((failure:any)=>failure.code).join('、')}}</p><div v-if="m.role==='assistant'&&m.model_name" class="message-meta">{{m.model_name}} · {{m.token_usage?.total_tokens??'—'}} tokens</div></article><div v-if="activeRun.busy" class="thinking"><i/><i/><i/> {{activeRun.status||'正在梳理资料'}}</div><div v-else-if="activeRun.error" class="stream-error" role="alert">{{activeRun.error}}</div></div>
<footer class="composer"><div class="mode-tabs"><button v-for="m in ['auto','knowledge','web','sql']" :class="{active:mode===m}" :disabled="m==='web'&&!webAvailable||m==='sql'&&!store.capabilities?.sql_enabled" :title="m==='web'&&!webAvailable?'联网搜索尚未启用':undefined" @click="mode=m as any">{{{auto:'自动调度',knowledge:'知识库',web:'联网 / 网页',sql:'业务 SQL'}[m]}}</button></div><textarea v-model="draft" maxlength="8000" placeholder="输入问题，Enter 发送，Shift + Enter 换行" @keydown.enter.exact.prevent="submit"/><button class="send" aria-label="发送问题" :disabled="!draft.trim()||activeRun.busy" @click="submit"><Send/></button><div class="usage"><div><Database/>缓存命中 <strong>{{lastMetrics?.cache?.by_model?.[0]?.hit_rate!=null?Math.round(lastMetrics.cache.by_model[0].hit_rate*100)+'%':'—'}}</strong></div><div><Zap/>预计上下文 <strong>{{estimate?`${Math.round(estimate.usage_ratio*100)}%`:'—'}}</strong><button v-if="estimate?.recommendation?.includes('compaction')&&sessionId" @click="compact">压缩</button></div></div></footer></section>
<div v-if="picker" class="modal-mask" @click.self="picker=false"><div class="modal"><header><h3>选择资料</h3><button class="icon" @click="picker=false"><X/></button></header><label v-for="d in store.readyDocuments"><input v-model="store.selectedDocuments" type="checkbox" :value="d.id"/>{{d.original_name}}</label><button class="primary" @click="picker=false">完成</button></div></div>
<aside v-if="citation" class="citation-panel" role="dialog" :aria-label="`引用 ${citation.number}`"><header><small>引用 {{citation.number}}</small><button class="icon" aria-label="关闭引用" @click="citation=null"><X/></button></header><div class="citation-heading"><h3>{{citation.type==='memory'?'长期记忆':citation.source_name||citation.title}}</h3><p>{{citationLocation(citation)}}</p></div><div ref="citationBody" class="citation-scroll"><p class="citation-location">高亮引用片段</p><blockquote><mark>{{citation.excerpt}}</mark></blockquote><template v-if="citation.type==='sql'"><p>返回 {{citation.row_count}} 行{{citation.truncated?' · 结果已截断':''}}</p><pre class="sql-query">{{citation.query}}</pre></template></div><footer><button class="ghost" @click="locateCitation"><LocateFixed/>定位回答中的引用</button><a v-if="citation.url" :href="citation.url" target="_blank" rel="noopener noreferrer">查看网页 <ChevronRight/></a></footer></aside>
</div></template>

<style scoped>
.agent-progress{list-style:none;padding:0;display:flex;gap:8px;flex-wrap:wrap;font-size:12px;color:var(--muted,#6b7280)}
.agent-progress li{border:1px solid var(--border,#e5e7eb);border-radius:6px;padding:5px 9px}
.agent-progress li[data-status="failed"],.agent-progress li[data-status="partial"]{color:#a33d30}
.sql-query{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px;line-height:1.6;padding:12px;background:var(--surface,#f6f6f6);border-radius:6px}
</style>
